"""Tooling advisor: holder (runout) advice and tool-series advice. Pure functions, stdlib only.

Units: lengths in inches, rpm in 1/min, SFM in ft/min.  Data files (all under ``data/``):

* ``holders.json``  holder types with cited TIR at the tool tip, clamping range, rigidity, balance.
* ``tool_series_performance.json``  generated by ``tools/build_tool_series_performance.py`` from
  ``tests/benchmarks/v2/*.json`` (series whose median published MRR beats the bucket median).
* ``tool_series.json``  curated, cited application notes.

The advisor never computes speeds or feeds; it only reads the inputs it is given.
"""
from __future__ import annotations

import json
import math
import os
from functools import lru_cache
from typing import Any, Dict, List, Optional

_DATA = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data")

MM_PER_IN = 25.4
OFFSET_FRACTION = 0.25            # tooth-to-tooth radial offset allowed as a fraction of fz
ULTRA_TIR_IN = 0.00015            # required TIR at or below this -> "ultra"
PRECISION_TIR_IN = 0.0003         # required TIR at or below this -> "precision"
HEAVY_DIAMETER_IN = 0.375         # tools >= 3/8" in heavy side-load roughing prefer stiff holders
HEAVY_OPERATIONS = ("rough", "slot")
BALANCE_RPM = 8000.0              # HAIMER rates whistle-notch holders only G6.3 @ 8,000 rpm
SPEEDER_SFM_FRACTION = 0.60       # recommend a speeder when SFM at max rpm < 60% of target
REF_PROJECTION_D = 3.0            # published TIR is quoted at about 3 x D from the nose
MAX_TOOL_ADVICE = 4

DIAMETER_BANDS = (("<=1/32", 1 / 32), ("1/32-1/16", 1 / 16), ("1/16-1/8", 1 / 8),
                  ("1/8-1/4", 1 / 4), ("1/4-1/2", 1 / 2), (">1/2", math.inf))
_NONFERROUS = ("Aluminum", "Copper", "Brass", "Bronze", "Magnesium", "Zinc")
_OP_ALIASES = {
    "slot": "slot", "slotting": "slot", "slot_full": "slot", "full_slot": "slot",
    "side": "side", "profile": "side", "contour": "side", "profiling": "side", "peripheral": "side",
    "hem": "hem", "adaptive": "hem", "dynamic": "hem", "trochoidal": "hem",
    "rough": "rough", "roughing": "rough", "pocket": "rough", "pocketing": "rough",
    "finish": "finish", "finishing": "finish",
    "tslot": "tslot", "t-slot": "tslot", "t_slot": "tslot", "keyseat": "tslot", "key_seat": "tslot",
    "tab": "tab", "tabs": "tab", "tab_milling": "tab",
}


# ---------------------------------------------------------------- data loading
@lru_cache(maxsize=None)
def _load(name: str) -> Dict[str, Any]:
    with open(os.path.join(_DATA, name), encoding="utf-8") as fh:
        return json.load(fh)


def diameter_band(dc_in: float) -> str:
    """Diameter band label (<=1/32, 1/32-1/16, 1/16-1/8, 1/8-1/4, 1/4-1/2, >1/2) for a diameter in inches."""
    for label, edge in DIAMETER_BANDS:
        if dc_in <= edge + 1e-6:
            return label
    return DIAMETER_BANDS[-1][0]


def material_group(family: str, hardness: Optional[dict] = None) -> Optional[str]:
    """Group a ToolWiz material family name into non_ferrous / steel / stainless / ti_ni_co / hardened / cast_iron.

    ``hardness`` is the benchmark-row dict ``{"min", "max", "scale"}``; steels with a minimum of
    45 HRC or more are 'hardened'.  Free-text names (``"316 stainless"``, ``"6061"``) are accepted.
    Returns None for materials the advisor does not cover.
    """
    f = (family or "").strip()
    low = f.lower()
    if f.startswith(_NONFERROUS) or any(k in low for k in ("alumin", "6061", "7075", "2024", "brass", "bronze", "copper", "magnesium")):
        return "non_ferrous"
    if "plastic" in low or low in ("delrin", "acetal", "acrylic", "pom", "peek", "nylon", "uhmw"):
        return "plastics"
    if "stainless" in low or any(k in low for k in ("316", "304", "17-4", "15-5", "420")):
        return "stainless"
    if any(low.startswith(p) for p in ("titanium", "high temp nickel", "nickel", "cobalt")) or any(
            k in low for k in ("titanium", "ti-6", "inconel", "waspaloy", "hastelloy", "monel")):
        return "ti_ni_co"
    if "cast iron" in low:
        return "cast_iron"
    if "steel" in low or any(k in low for k in ("4130", "4140", "4340", "1018", "1020", "1045", "a2", "d2", "h13", "o1", "s7")) or low.startswith("steel"):
        h = hardness or {}
        if "hardened" in low or (h.get("scale") == "HRC" and (h.get("min") or 0) >= 45):
            return "hardened"
        return "steel"
    return None


def normalize_operation(operation: str) -> Optional[str]:
    """Map a free-text operation name to slot/side/hem/rough/finish/tslot/tab, or None when unknown."""
    return _OP_ALIASES.get((operation or "").strip().lower().replace(" ", "_"))


# ---------------------------------------------------------------- holder advice
def required_tir_in(fz_in: float, flutes: int) -> float:
    """Largest TIR (inches) that keeps the tooth-to-tooth radial offset within 25% of the chip load.

    The offset between adjacent teeth is TIR x sin(pi / flutes); every flute shares the load when
    that offset is at most 0.25 x fz.  A single-flute tool has no tooth-to-tooth offset and is
    treated as a two-flute tool (sin(pi/2) = 1) so the number stays conservative.
    """
    z = max(2, int(flutes))
    return OFFSET_FRACTION * float(fz_in) / math.sin(math.pi / z)


def runout_summary(diameter_in: float, runout_in: float, fz_in: float, flutes: int) -> Dict[str, Any]:
    """Runout check for the UI: required TIR, tooth-to-tooth offset, offset/fz ratio and whether it passes.

    ``ratio`` is the tooth-to-tooth radial offset divided by fz (0.25 or less = all flutes share the load).
    """
    z = max(2, int(flutes))
    offset = float(runout_in) * math.sin(math.pi / z)
    req = required_tir_in(fz_in, flutes)
    return {"required_tir_in": req, "tooth_offset_in": offset,
            "ratio": offset / fz_in if fz_in > 0 else None, "ok": runout_in <= req}


def _holder_class(req_in: float) -> str:
    if req_in <= ULTRA_TIR_IN:
        return "ultra"
    if req_in <= PRECISION_TIR_IN:
        return "precision"
    return "standard"


def _tip_tir_in(h: dict, diameter_in: float, stickout_in: Optional[float]) -> float:
    """Worst-case published TIR of holder ``h`` at the tool tip (inches).

    Uses the clamping-diameter table when the source publishes one, then scales linearly for a
    projection longer than the ~3 x D at which TIR is quoted (a fixed angular error grows with length).
    """
    d_mm = diameter_in * MM_PER_IN
    tir_mm = h["tir_mm"]
    for row in h.get("tir_by_clamp_mm") or []:
        tir_mm = row["tir_mm"]
        if d_mm <= row["d_max_mm"]:
            break
    scale = 1.0
    if stickout_in and diameter_in > 0:
        scale = max(1.0, stickout_in / (REF_PROJECTION_D * diameter_in))
    return tir_mm / MM_PER_IN * scale


def _speeder_text(diameter_in: float, sfm_target: float, max_rpm: float) -> Optional[str]:
    """Recommendation text for a spindle speeder / high-speed attachment, or None when not needed."""
    if not sfm_target or diameter_in <= 0:
        return None
    sfm_max = math.pi * diameter_in * max_rpm / 12.0
    if sfm_max >= SPEEDER_SFM_FRACTION * sfm_target:
        return None
    need_rpm = sfm_target * 12.0 / (math.pi * diameter_in)
    pct = 100.0 * sfm_max / sfm_target
    fits = []
    for a in _load("holders.json")["speed_attachments"]:
        lo, hi = a["tool_range_in"]
        if not (lo <= diameter_in <= hi):
            continue
        top = max(a["max_rpm"].values())
        names = [k for k, v in sorted(a["max_rpm"].items(), key=lambda kv: kv[1]) if v >= need_rpm]
        if not names and top < 0.6 * need_rpm:
            continue
        model = names[0] if names else max(a["max_rpm"], key=a["max_rpm"].get)
        rng = a["max_rpm"][model]
        fits.append(f"{a['vendor']} {a['name']} ({model}, up to {rng:,} rpm, tools {lo:.3f}-{hi:.3f} in; {a['drive']}; {a['caveats']})")
    head = (f"The {max_rpm:,.0f} rpm spindle gives only {sfm_max:,.0f} SFM ({pct:.0f}% of the {sfm_target:,.0f} SFM target); "
            f"the target needs about {need_rpm:,.0f} rpm. A BT30 spindle speeder / high-speed attachment class is worth considering "
            "for finishing and light cuts: ")
    if not fits:
        return head + ("none of the cited BT30 attachments covers this diameter and speed; accept the reduced SFM "
                       "and lower the chip load to keep the tool cutting rather than rubbing.")
    return head + " | ".join(fits) + (". Check BT30 vs BIG-PLUS (BBT30) spindle compatibility, automatic tool change, "
                                      "and power: these attachments deliver tens to a few hundred watts.")


def holder_advice(diameter_in: float, runout_in: float, fz_in: float, flutes: int, rpm: float,
                  operation: str, stickout_in: Optional[float], max_rpm: float = 16000,
                  sfm_target: Optional[float] = None, taper: str = "BT30") -> Dict[str, Any]:
    """Toolholder advice from the runout the process needs.

    Inputs (inches, rpm): tool diameter, measured or assumed TIR ``runout_in``, chip load ``fz_in``
    (in/tooth), flute count, spindle ``rpm``, ``operation`` (slot/side/hem/rough/finish...), tool
    ``stickout_in``, machine ``max_rpm``, optional ``sfm_target`` (ft/min) and spindle ``taper``.

    The required TIR is 0.25 x fz / sin(pi / flutes) so every flute shares the load.  Each holder's
    cited tip TIR (``data/holders.json``) is compared with it: holders at or below half the requirement are
    recommended, those at or below the requirement are acceptable, the rest are avoided.  When no holder
    reaches half the requirement the best published tier is recommended.  Heavy side-load roughing on
    tools of 3/8 in or more recommends only stiff holders (shrink fit, powRgrip, milling chuck, SK).

    Returns ``{"required_tir_in", "class", "recommended", "acceptable", "avoid", "reason",
    "high_speed_spindle", "sources"}``.
    """
    if diameter_in is None or diameter_in <= 0:
        raise ValueError("diameter_in must be > 0")
    if fz_in is None or fz_in <= 0:
        raise ValueError("fz_in must be > 0")
    flutes = int(flutes or 2)
    if flutes < 1:
        raise ValueError("flutes must be >= 1")
    runout_in = float(runout_in or 0.0)
    op = normalize_operation(operation) or (operation or "").lower()
    req = required_tir_in(fz_in, flutes)
    cls = _holder_class(req)
    heavy = op in HEAVY_OPERATIONS and diameter_in >= HEAVY_DIAMETER_IN

    data = _load("holders.json")
    srcs = data["sources"]
    cand = []
    for h in data["holders"]:
        if diameter_in * MM_PER_IN > h["clamp_mm"][1] or (h["id"] == "micro_collet_chuck" and diameter_in * MM_PER_IN > 8.0):
            continue
        cand.append((h, _tip_tir_in(h, diameter_in, stickout_in)))
    best = min(t for _, t in cand)
    recommended, acceptable, avoid, demoted = [], [], [], []
    # With margin: recommended <= req/2.  If nothing reaches that, the best published tier is recommended.
    rec_limit = req / 2.0 if best <= req / 2.0 else best * 1.25
    for h, tir in cand:
        if tir <= rec_limit:
            recommended.append(h)
        elif tir <= req * 1.0000001:
            acceptable.append(h)
        else:
            avoid.append(h)
    if heavy:
        keep = []
        for h in recommended:
            if h["rigidity"] == "stiff":
                keep.append(h)
            else:
                demoted.append(h)
        recommended = keep
        acceptable = demoted + acceptable
    # preference order inside the lists
    pref = ["shrink_fit", "powrgrip", "milling_chuck", "sk_collet_chuck", "hydraulic", "micro_collet_chuck",
            "er_ultra_precision", "er_standard", "weldon"]
    if diameter_in <= 0.125 and not heavy:
        pref.insert(0, pref.pop(pref.index("micro_collet_chuck")))
    rank = {k: i for i, k in enumerate(pref)}
    for lst in (recommended, acceptable, avoid):
        lst.sort(key=lambda h: rank.get(h["id"], 99))

    reason = [f"Required TIR at the tool tip is {req:.5f} in ({req * 25400:.1f} um): the tooth-to-tooth radial offset TIR x "
              f"sin(pi/{flutes}) must stay within 25% of the {fz_in:.5f} in/tooth chip load so all {flutes} flutes cut. "
              f"That is {'an' if cls == 'ultra' else 'a'} {cls} requirement."]
    if runout_in > 0:
        if runout_in > req:
            reason.append(f"The runout entered ({runout_in:.5f} in) is above that limit, so some flutes will cut little or nothing "
                          "and the working chip load on the others is higher than programmed.")
        else:
            reason.append(f"The runout entered ({runout_in:.5f} in) is within that limit.")
    if best > req / 2.0:
        reason.append("No holder's published spec leaves a 2x margin on that requirement (best about "
                      f"{best:.5f} in at the tip), so the best tier is recommended: keep the stickout short and measure the assembly.")
    if stickout_in and diameter_in > 0 and stickout_in > REF_PROJECTION_D * diameter_in:
        reason.append(f"Stickout is {stickout_in / diameter_in:.1f} x D; published TIR is quoted near 3 x D, so tip TIR was scaled up in proportion.")
    if heavy:
        reason.append("Heavy side-load roughing on a tool of 3/8 in or more favors the stiff holders (shrink fit, powRgrip, milling chuck). "
                      "HAIMER lists its Power and Heavy Duty shrink chucks for roughing and reports hydraulic and reinforced shrink chucks "
                      "could not prevent tool pull-out in an aerospace roughing trial that needed Safe-Lock, and mechanical milling chucks "
                      "trade some runout for clamping force; hydraulic chucks suit finishing, drilling and light milling.")
    rpm_hi = max(float(rpm or 0.0), 0.0)
    if rpm_hi > BALANCE_RPM or max_rpm > BALANCE_RPM:
        reason.append(f"At up to {max(rpm_hi, float(max_rpm)):,.0f} rpm balance matters: use holders balanced to G2.5 or better "
                      "(shrink and hydraulic holders are listed at G2.5 at 25,000 rpm; HAIMER lists whistle-notch holders only at G6.3 at 8,000 rpm), "
                      "and balanced nuts on ER collets.")
    reason.append("Check the assembly with an indicator or a Blum / laser measurement at the tool tip and enter the measured TIR; "
                  "re-measure after changing collets, tools or nuts.")
    if taper and taper.upper() != "BT30":
        reason.append(f"Holder data assumes a BT30-class interface; confirm availability for {taper}.")

    used = {s for h in recommended + acceptable + avoid for s in h["sources"]}
    speeder = _speeder_text(diameter_in, sfm_target, float(max_rpm)) if sfm_target else None
    if speeder:
        for a in data["speed_attachments"]:
            used.update(a["sources"])
    return {
        "required_tir_in": round(req, 6),
        "class": cls,
        "recommended": [h["label"] for h in recommended],
        "acceptable": [h["label"] for h in acceptable],
        "avoid": [h["label"] for h in avoid],
        "reason": " ".join(reason),
        "high_speed_spindle": speeder,
        "sources": [f"{srcs[s]['label']} - {srcs[s]['url']}" for s in sorted(used)],
    }


# ---------------------------------------------------------------- tool advice
_GROUP_LABEL = {"non_ferrous": "aluminum / non-ferrous", "steel": "steel", "stainless": "stainless steel",
                "ti_ni_co": "titanium / nickel / cobalt alloys", "hardened": "hardened steel",
                "cast_iron": "cast iron", "plastics": "plastics"}


def tool_advice(family: str, diameter_in: float, operation: str, flutes: Optional[int] = None,
                coating: Optional[str] = None) -> List[Dict[str, Any]]:
    """Tool-series recommendations for a material family, diameter (inches) and operation; at most 4.

    Two sources: (a) series whose median published MRR (ap x ae x fz x flutes x rpm) is at least 1.3 x
    the bucket median with at least two supporting benchmark rows (``data/tool_series_performance.json``),
    ranked by gain; (b) curated, cited application notes (``data/tool_series.json``) ranked by their
    ``impact`` weight.  ``flutes`` and ``coating`` describe the user's current tool and are used only to
    word the explanation.  Returns a list of ``{"vendor", "series", "applies_to", "why", "expected_gain",
    "evidence"}`` ordered by expected impact; empty when nothing applies.
    """
    if diameter_in is None or diameter_in <= 0:
        raise ValueError("diameter_in must be > 0")
    op = normalize_operation(operation)
    if op is None:
        raise ValueError(f"unknown operation {operation!r}")
    group = material_group(family)
    if group is None:
        return []
    band = diameter_band(diameter_in)
    scored: List[tuple] = []

    bucket_op = "slot" if op == "tab" else op
    perf = _load("tool_series_performance.json")["buckets"].get(f"{group}|{bucket_op}|{band}")
    if perf and op != "tslot":
        for e in perf["recommended"]:
            gain = e["gain_vs_bucket_median"]
            same = bool(flutes and e["flutes"] == [flutes] and coating and coating.lower() in [c.lower() for c in e["coatings"]])
            why = (f"Median published material removal rate {e['median_mrr_in3_min']:.3f} in^3/min over {e['rows']} {e['vendor']} rows, "
                   f"against {perf['bucket_median_mrr_in3_min']:.3f} in^3/min for all {perf['bucket_rows']} vendor rows in this bucket "
                   f"({', '.join(perf['vendor_groups'])}). These are the vendors' own recommendations, so prove them with a test cut.")
            if same:
                why += " Your current flute count and coating match this series; the gain comes from its geometry and grade."
            scored.append((gain, {
                "vendor": e["vendor"], "series": e["series"],
                "applies_to": f"{_GROUP_LABEL.get(group, group)}, {op} operation, {band} in diameter"
                              + (f", {'/'.join(str(x) for x in e['flutes'])} flute" if e["flutes"] else ""),
                "why": why,
                "expected_gain": f"+{(gain - 1) * 100:.0f}% MRR vs bucket median (published data, {e['rows']} rows)",
                "evidence": list(e["evidence"])}))

    for s in _load("tool_series.json")["series"]:
        if group not in s["groups"] or op not in s["ops"]:
            continue
        if s.get("diameter_in"):
            lo, hi = s["diameter_in"]
            if not lo <= diameter_in <= hi:
                continue
        scored.append((float(s["impact"]), {
            "vendor": s["vendor"], "series": s["series"], "applies_to": s["applies_to"],
            "why": s["why"] + f" Source: {s['citation_url']}",
            "expected_gain": "application fit per the manufacturer's stated use; no benchmark gain computed",
            "evidence": []}))

    scored.sort(key=lambda t: (-t[0], t[1]["vendor"], t[1]["series"]))
    return [d for _, d in scored[:MAX_TOOL_ADVICE]]
